<script setup lang="ts">
import { ref, reactive, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import { useUserStore } from '@/store/user'
import { showToast, showConfirmDialog } from 'vant'
import { useTimeUtils } from '@/utils/time'
import { useAppStore } from '@/store/index'
const userTime = useTimeUtils();
// 路由和状态管理
const router = useRouter()
const userStore = useUserStore()
const appStore = useAppStore()
const tits = ref('修改退水')
const num = ref(3)
const props = defineProps(['id'])

// Data
const value1 = ref(10100)
const lotteryName = ref('')
const shawList = ref([])
const earnWater = ref(0)
const earnOdds = ref(0)
const userInfo = ref({})
const ids = ref('')
const loading = ref(false)
const isA = ref(false)
const isB = ref(false)
const isC = ref(false)
const isD = ref(false)
const minBet = ref(0)
const maxBet = ref(0)
const maxPeriod = ref(0)
const radio = ref(1)
const classList = ref([])
const zdSelect = ref(false)

// Methods
const changes = (obj) => {
  if (obj.selected) {
    obj.selected = false
  } else {
    obj.selected = true
  }
}

const maxClist = (ots) => {
  if (ots.maxBet > ots.upInfo.maxBet) {
    ots.maxBet = ots.upInfo.maxBet
    if (ots.maxPeriod > ots.maxBet) {
      showToast({
        type: 'error',
        message: '注单限额不能大于单期限额'
      })
    }
  } else {
    if (ots.maxPeriod > ots.maxBet) {
      showToast({
        type: 'error',
        message: '注单限额不能大于单期限额'
      })
    }
  }
}

const pdownOdds = (item) =>{
    item.oddsList.map(its=>{
        its.downOdds = item.oneOdds.downOdds;
    })
}
const filteredList = (item) => {
  return item.replace(/当年度/g, '')
}

const paBreak = (item) => {
  item.infoList.forEach(its => {
    its.abreak = item.abreak
  })
}
const reduceHandle = (): void => {
    if (isNaN(earnWater.value)) {
        console.log('请输入确定数字')
        return
    }
    
    classList.value.forEach(item => {
        item.oddsList.forEach(odds => {
            reduceWater(odds)
        })
    })
}
const pAtabs = (its,num) => {
        its.oddsList.forEach(item => {
            switch(num) {
                case 1:
                    item.abreak = its.oneOdds.abreak
                    break
                case 2:
                    item.bbreak = its.oneOdds.bbreak
                    break
                case 3:
                    item.cbreak = its.oneOdds.cbreak
                    break
                case 4:
                    item.dbreak = its.oneOdds.dbreak
                    break
                case 5:
                    item.minBet = its.oneOdds.minBet
                    break
                case 6:
                    item.maxBet = its.oneOdds.maxBet
                    break
                case 7:
                    item.maxPeriod = its.oneOdds.maxPeriod
                    break
            }
        })
}
const operate = (num) => {
    classList.value.forEach(list => {
       // list.oneOdds.abreak = tspams.aBreak;
       // list.oneOdds.bbreak = tspams.bBreak;
      //  list.oneOdds.cbreak = tspams.cBreak;
       // list.oneOdds.dbreak = tspams.dBreak;
        list.oneOdds.minBet = minBet.value;
        list.oneOdds.maxBet = maxBet.value;
        list.oneOdds.maxPeriod = maxPeriod.value;
        list.oddsList.forEach(item => {
            switch(num) {
                case 1:
                    item.abreak = tspams.aBreak
                    break
                case 2:
                    item.bbreak = tspams.bBreak
                    break
                case 3:
                    item.cbreak = tspams.cBreak
                    break
                case 4:
                    item.dbreak = tspams.dBreak
                    break
                case 5:
                    item.abreak = tspams.aBreak
                    item.bbreak = tspams.bBreak
                    item.cbreak = tspams.cBreak
                    item.dbreak = tspams.dBreak
                    break
                case 6:
                    item.minBet = minBet.value
                    break
                case 7:
                    item.maxBet = maxBet.value
                    break
                case 8:
                    item.maxPeriod = maxPeriod.value
                    break
                case 9:
                    item.minBet = minBet.value
                    item.maxBet = maxBet.value
                    item.maxPeriod = maxPeriod.value
                    break
            }
        })
    })
}

const lxtab = () => {
  zdSelect.value = !zdSelect.value
}

const onSelect = (item) => {
  value1.value = item.lotteryId
  lotteryName.value = item.lotteryName
  minBet.value = 0
  maxBet.value = 0
  maxPeriod.value = 0
  earnWater.value = 0
  earnOdds.value = 0
  getLoadBreak()
}

const oddsHandle = () => {
  if (isNaN(earnOdds.value)) {
    showToast({ type: 'error', message: '请输入确定数字' })
    return
  }
  classList.value.forEach(item => {
    item.oneOdds.downOdds = earnOdds.value
    item.oddsList.forEach(its => {
      its.downOdds = earnOdds.value
    })
  })
}


const getLoadBreak = async () => {
  classList.value = []
  try {
    const res = await userStore.getLoadMkBreak(props.id,value1.value)
    if (res.code === 200 && res.data.length > 0) {
      classList.value = res.data
    }
    await nextTick()
  } catch (error) {
    console.error('getLoadBreak error:', error)
    Toast({ type: 'error', message: '加载数据失败' })
  }
}

const getUserInfo = async () => {
  shawList.value = []
  try {
    const res = await userStore.getQueryOrg(props.id)
    userInfo.value = res.data
    if (res.data.handicapList && res.data.handicapList.length > 0) {
      for (let j = 0; j < res.data.handicapList.length; j++) {
        if (res.data.handicapList[j] == 1) {
          isA.value = true
        }
        if (res.data.handicapList[j] == 2) {
          isB.value = true
        }
        if (res.data.handicapList[j] == 3) {
          isC.value = true
        }
        if (res.data.handicapList[j] == 4) {
          isD.value = true
        }
      }
    }
    if (res.data.lotteryList && res.data.lotteryList.length > 0) {
      shawList.value = res.data.lotteryList
      value1.value = res.data.lotteryList[0].lotteryId
      lotteryName.value = res.data.lotteryList[0].lotteryName
    }
    getLoadBreak()
  } catch (error) {
    console.error('getUserInfo error:', error)
    Toast({ type: 'error', message: '获取用户信息失败' })
  }
}

const check_count = (e) => {
  let obj = e.target
  if (obj.value != '' && obj.value.substr(0, 1) == '.') {
    obj.value = ""
  }
  obj.value = obj.value.replace(/^0*(0\.|[1-9])/, '$1')
  obj.value = obj.value.replace(/^(\-)*(\d+)\.(\d\d\d\d).*$/, '$1$2.$3')
  if (obj.value.indexOf(".") < 0 && obj.value != "") {
    if (obj.value.substr(0, 1) == '0' && obj.value.length == 2) {
      obj.value = obj.value.substr(1, obj.value.length)
    }
  }
}
const reduceWater = (item) => {
    const sum = (x: number, y: number) => (x * 1000 - y * 1000) / 1000
    
    const a_water = sum(item.paBreak, earnWater.value)
    const b_water = sum(item.pbBreak, earnWater.value)
    const c_water = sum(item.pcBreak, earnWater.value)
    const d_water = sum(item.pdBreak, earnWater.value)

    item.abreak = a_water > 0 ? a_water : 0
    item.bbreak = b_water > 0 ? b_water : 0
    item.cbreak = c_water > 0 ? c_water : 0
    item.dbreak = d_water > 0 ? d_water : 0

    return item
}
const saveWater = async (): Promise<void> => {
    loading.value = true

    try {
        await showConfirmDialog({
            title: '是否修改當前退水。',
            messageAlign: 'center',  // 设置 message 居中
            width: '85vw',  
        })
        let hasExceeded = false
        let hasEmpty = false
        let hasEmptyList = false

        classList.value.forEach(list => {
            if (list.oddsList.length > 0) {
                list.oddsList.forEach(item => {
                    if (item.abreak > item.paBreak || item.bbreak > item.pbBreak || 
                        item.cbreak > item.pcBreak || item.dbreak > item.pdBreak) {
                        hasExceeded = true
                    }
                    if (item.abreak < 0 || item.bbreak < 0 || item.cbreak < 0 || item.dbreak < 0 || 
                        item.minBet < 0 || item.maxBet < 0 || item.maxPeriod < 0) {
                        hasEmpty = true
                    }
                })
            } else {
                hasEmptyList = true
            }
        })

        if (hasExceeded) {
            showToast("当前有退水超过上级")
            return
        }
        if (hasEmpty || hasEmptyList) {
            showToast('保存数据有空值,请检查!')
            return
        }

        const params = {
            vos: classList.value,
            type: radio.value
        }

        const res: ApiResponse = await userStore.waterSave(params);
        showToast({
            type:'success',
            message: '操作成功',
            duration: 1500
        })
        ids.value = props.id
        setTimeout(() => {
            getLoadBreak()
        }, 1000)

    } catch (error) {
        console.error('保存失败:', error)
        if (error !== 'cancel') {
            console.log('保存失败')
        }
    } finally {
        loading.value = false
    }
}

// 生命周期 - created 对应 onMounted
onMounted(() => {
  getUserInfo()
})
</script>
